#pragma once
#include <cstdio>

// The command line help (--help); the options themselves are parsed in options.h.
inline void PrintUsage()
{
    std::puts("pw_bench12 [frames=600] --gltf file.glb [--hdri file.hdr]\n"
        "  --interactive --settings file (interactive defaults to settings.json beside exe)\n"
        "  --width 1920 --height 1080 --render-scale 0.5 --spp 1 --bounces 0..8\n"
        "  --render pathtrace|raster --raster-ambient 0.165 --hud --render-switch-at F (frame F flips raster <-> pathtrace)\n"
        "  --no-instancing (meshes shared by static nodes are flattened per node, as before instancing; --lightmap always flattens)\n"
        "  --cpu-skinning (characters and wind skinned by CPU workers and uploaded, as before the GPU skinning pass)\n"
        "  --cull-small-radius 0.75 --cull-cone-deg 170 --cull-small-distance 0 --no-small-culling --no-occlusion-culling --cull-check --cull-debug\n"
        "    (raster: instances with a bounding sphere below the radius leave every pass outside the cone around the view or beyond the\n"
        "     distance; the camera passes also drop them when Hi-Z occluded; check: draw all, list culled-but-visible; debug: red overlay)\n"
        "  --wind --wind-strength 1 (veg_ nodes sway: a CPU displacement per frame, the frame index is the clock; none in the scene: a warning)\n"
        "  --raster-sky-ambient (raster, needs --hdri: the ambient term is the HDRI sky's SH9 irradiance instead of the constant)\n"
        "  --probes --probe-spacing 1 --probe-rays 256 --probe-dump file (raster: the ambient term from irradiance probes traced once at start)\n"
        "  --lamp-tubes (raster: each emissive tube of a lamp group is a line light, compact emitters stay point lights)\n"
        "  --lamp-shadows (raster: a spot shadow map per lamp group; with --lightmap a bake with the \"lamp\" map)\n"
        "  --fxaa (raster: FXAA 3.11 on the finished frame, before the upscaler, NR and the add-on)\n"
        "  --sky-reflections 0|1 (raster: the sky's image-based specular, occluded by --ao and the probes; default on with --hdri)\n"
        "  --lightmap lab_lightmap.json (raster: static geometry lit from baked lightmaps; needs a glb with TEXCOORD_1)\n"
        "  --csm --csm-stable 0|1 --csm-distance 100 (raster: sun shadow in 4 cascades) --ao clean|game --ao-radius 1 --ao-strength 1 --ao-alpha 0.1 (raster: ambient occlusion; alpha: game's history blend, 1 = none)\n"
        "  --camera static|yaw|forward|strafe|combo|script|follow|snap --yaw-speed 45 --move-speed 2 --sway 0\n"
        "  --snap-deg 90 --snap-frames 6 --snap-hold 54 (snap: an in-place turn of DEG over FRAMES, held, and back)\n"
        "  --anim-speed 1 --anim-start 0 --anim-playing 0|1 --blas-rebuild 60 --follow-node NAME\n"
        "  --cam-dolly 0 --cam-lift 0 --cam-pos x,y,z --cam-target x,y,z --fov 60\n"
        "  --sun-dir x,y,z --sun-strength 1 --sun-angle 0.5 --exposure 1.45 --albedo 1\n"
        "  --firefly 50 --jitter 0|1 --depth standard|reverse|linear-negative|linear-positive --motion pixels|ndc|none\n"
        "  --haze 0.012 --haze-g 0.6 --tonemap aces|neutral|none|ue-filmic --bloom 0.06 --auto-exposure 0|1\n"
        "  --exposure-speed-up 3 --exposure-speed-down 1.5 --exposure-ev 0 --exposure-centre 0 (auto exposure)\n"
        "  --exposure-metering bench|ue --exposure-min-ev 0.5 --exposure-max-ev 20 (ue: UE histogram 10..90 % mean to 18 %, EV100 bounds)\n"
        "  --exposure-curve 3,6,0.33 (ue metering: + EV stops from scene EV100 3 to 6 and above, as UE's Exposure Compensation Curve)\n"
        "  --film-slope 0.88 --film-toe 0.55 --film-shoulder 0.26 --film-black-clip 0 --film-white-clip 0.04 (--tonemap ue-filmic)\n"
        "  --local-exposure 0|1 --local-exposure-highlights 0.8 --local-exposure-shadows 0.8 --local-exposure-detail 1 --local-exposure-blend 0.6\n"
        "  --light-candidates 8 --vsync 0|1 --upscaler none|sr|rr (quality from render scale)\n"
        "  --host ngx|core --core-mode 0|1|2 --core-temporal 0|1 --core-warp-path 0|1|2 (core: native NR, sRGB, SR)\n"
        "  --core-state-sentinel draw|compute (diagnostic NGX state check)\n"
        "  --core-state-rebind (explicit host rebinding before the next draw or dispatch)\n"
        "  --nr off|native|upscale (DLSS Neural Rendering host) --nr-colour srgb|linear --nr-log 0|1|2\n"
        "  --nr-output-pad X,Y[,BX,BY] --nr-colour-pad X,Y --nr-pause A,B[,A2,B2...] (skip the NR evaluate on frames A..B-1)\n"
        "  --nr-pause-show frozen|input (a paused frame presents the last NR output, or its own NR input)\n"
        "  --nr-recreate F (frame F releases feature 18 and creates it again) --resize-at F[,W,H] (frame F resizes the swap chain)\n"
        "  --nr-release-thread (the --nr-recreate release runs on a second thread during frame F's present)\n"
        "  --texture-cache DIR (the scene images' decoded mip chains, read back on the next start; no effect on the frames)\n"
        "  --startup-profile (prints the wall time of the run's phases from the process's creation at the end)\n"
        "  --nr-reset-at F[,F2...] (frame F's NR evaluate reads DLSSNR.Reset=1: the model and the add-on's core drop their history)\n"
        "  --recreate-swapchain F (frame F destroys the swap chain and creates a new one on the same window)\n"
        "  --set-at F,ID,VALUE[,F2,ID2,VALUE2...] (frame F sets add-on setting ID to the integer VALUE through its export)\n"
        "  --mv-format rg16f|rgba16f (motion texture handed to DLSS/NR)\n"
        "  --view colour|noisy|accum|depth|motion|normal|roughness|albedo|specular|vegmask (raster: foliage class*50 in red) --dump N[,N...] --dump-format bmp|png (png: lossless, about 3-5x smaller) --debug-layer\n"
        "  --dump-raw motion|depth|motion,depth (per --dump frame: motion_N.f32, OFMV header, float32 x,y current->previous\n"
        "     render pixels; depth_N.f32, OFDP header, the float32 depth guide at render size)\n"
        "  --dump-raw prevdepth (alone; per --dump frame: prevdepth_N.f32, OFPD header, float32 view depth in metres of each\n"
        "     pixel's surface in the camera of frame t-span; the motion guide carries it, so the run is for this dump only)\n"
        "  --motion-span 1..64 (motion of frame t is the offset to t-K; not with --camera follow or --interactive)\n"
        "  --motion-span cadence --cadence 2..8 --cadence-phase P (motion of frame t is the offset to its last full pass)\n"
        "  --start-frame S (start at frame S as if 0..S-1 had run; no NR/RR/core history) --exposure-record FILE | --exposure-replay FILE");
}
